"""Nguồn chuẩn cho schema SQL, từ điển dữ liệu và ERD. Python 3, không cần thư viện ngoài."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
TABLES = []
ORIGINAL = set('Roles Users Areas Branches AreaManagers StaffBranches Categories Products BranchProducts Customers CustomerPreferences Orders OrderDetails LoyaltyTransactions Promotions CustomerPromotions Feedbacks Surveys SurveyQuestions SurveyRecipients SurveyResponses'.split())

def c(name, typ, why, example='', nullable=False, default=None, ref=None, source='Backend kiểm tra và ghi từ dữ liệu người dùng hoặc nghiệp vụ tương ứng.'):
    return dict(name=name, type=typ, why=why, example=str(example), nullable=nullable, default=default, ref=ref, source=source)

def idc(name):
    return c(name,'int IDENTITY(1,1)','Định danh ổn định để liên kết bản ghi; không dùng tên có thể thay đổi làm khóa.',1,source='SQL Server sinh khi tạo bản ghi.')

def fk(name, table, nullable=False, why=None):
    return c(name,'int',why or f'Liên kết tới {table}; khóa ngoại ngăn tham chiếu bản ghi không tồn tại.',1,nullable,ref=f'{table}.{name}')

def at(name='CreatedAt', nullable=False):
    return c(name,'datetime2(3)','Thời điểm UTC phục vụ lịch sử và đối chiếu; giao diện đổi sang giờ Việt Nam.','2026-09-17T03:00:00Z',nullable, None if nullable else 'SYSUTCDATETIME()',source='Backend/SQL Server ghi khi sự kiện tương ứng xảy ra.')

def flag(name='IsActive', why='Cho phép ngừng sử dụng mà không xóa lịch sử đã tham chiếu.', default='1'):
    return c(name,'bit',why,default,default=default)

def money(name, why, default=None):
    return c(name,'decimal(18,2)',why+' Số thập phân chính xác tránh sai số cộng tiền.',35000,default=default)

def rv():
    return c('Version','rowversion','Dấu phiên bản để phát hiện ghi đè dữ liệu khi hai người cùng sửa; không phải thời gian.','0x00000000000007D1',source='SQL Server tự cập nhật mỗi lần ghi.')

def t(name, group, purpose, cols, pk, checks=(), uniques=()):
    TABLES.append(dict(name=name,group=group,purpose=purpose,columns=cols,pk=pk.split(','),checks=list(checks),uniques=[x.split(',') for x in uniques],original=name in ORIGINAL))

